new = '''def solve_plan(R):
    caps = R["caps"]
    F = R["flows"]
    warmup = R["warmup"]
    ben = {}
    for fid, seq in R["runs"].items():
        ben[fid] = flow_benefit(F[fid], seq, warmup)
    used = dict((n, 0) for n in caps)
    forced = []
    pinned = set(R["pinned"])
    for fid in R["pinned"]:
        for n in F[fid]["path"]:
            used[n] += 1
        forced.append(fid)
    for n, c in used.items():
        if c > caps[n]:
            return {"infeasible": True}
    base_val = sum(ben[fid] for fid in forced)
    avail = dict((n, caps[n] - used[n]) for n in caps)
    items = []
    for fid in sorted(F):
        if fid in pinned or ben[fid] <= 0:
            continue
        items.append((fid, ben[fid], F[fid]["path"]))
    # drop items that cannot ever fit, propagate capacity-zero blocks
    changed = True
    while changed:
        changed = False
        keep = []
        for it in items:
            if any(avail[n] <= 0 for n in it[2]):
                changed = True
                continue
            keep.append(it)
        items = keep
    if not items:
        return _finish(forced, [], ben, base_val)
    cnt_per_node = {}
    for fid, b, path in items:
        for n in set(path):
            cnt_per_node[n] = cnt_per_node.get(n, 0) + 1
    binding = sorted(n for n, c in cnt_per_node.items() if c > avail[n])
    if not binding:
        return _finish(forced, [it[0] for it in items], ben, base_val)
    bind_index = dict((n, i) for i, n in enumerate(binding))
    m = len(binding)
    cap_left = [avail[n] for n in binding]
    groups = {}
    for fid, b, path in items:
        nodes = tuple(sorted(set(bind_index[n] for n in path if n in bind_index)))
        groups.setdefault((nodes, b), []).append(fid)
    gl = [(b, nodes, len(fids), fids)
          for (nodes, b), fids in groups.items()]
    gl.sort(key=lambda g: (-g[0], len(g[1]), g[1]))
    G = len(gl)
    suff_val = [0] * (G + 1)
    suff_cnt = [0] * (G + 1)
    suff_use = [[0] * m for _ in range(G + 1)]
    for i in range(G - 1, -1, -1):
        b, nodes, k, _f = gl[i]
        suff_val[i] = suff_val[i + 1] + b * k
        suff_cnt[i] = suff_cnt[i + 1] + k
        cur = list(suff_use[i + 1])
        for n in nodes:
            cur[n] += k
        suff_use[i] = cur
    best = [0, 0, []]  # extra value, extra count, chosen flow ids
    chosen = []
    seen = {}

    def dfs(i, val, cnt, left):
        if val > best[0] or (val == best[0] and cnt < best[1]):
            best[0] = val
            best[1] = cnt
            best[2] = list(chosen)
        if i >= G:
            return
        ub = val + suff_val[i]
        if ub < best[0] or (ub == best[0] and cnt >= best[1]):
            return
        su = suff_use[i]
        fits = True
        for n in range(m):
            if su[n] > left[n]:
                fits = False
                break
        if fits:
            v = ub
            c = cnt + suff_cnt[i]
            if v > best[0] or (v == best[0] and c < best[1]):
                best[0] = v
                best[1] = c
                best[2] = chosen + [f for g in gl[i:] for f in g[3]]
            return
        key = (i, tuple(left))
        prev = seen.get(key)
        if prev is None:
            seen[key] = [(val, cnt)]
        else:
            for pv, pc in prev:
                if pv >= val and pc <= cnt:
                    return
            prev.append((val, cnt))
        b, nodes, k, fids = gl[i]
        jm = k
        for n in nodes:
            if left[n] < jm:
                jm = left[n]
        for j in range(jm, 0, -1):
            nv = val + j * b
            if nv + suff_val[i + 1] < best[0]:
                break
            if nv + suff_val[i + 1] == best[0] and cnt + j >= best[1]:
                continue
            for n in nodes:
                left[n] -= j
            chosen.extend(fids[:j])
            dfs(i + 1, nv, cnt + j, left)
            del chosen[-j:]
            for n in nodes:
                left[n] += j
        dfs(i + 1, val, cnt, left)

    dfs(0, 0, 0, cap_left)
    return _finish(forced, best[2], ben, base_val)


'''
